#include <cstdint>
static inline uint32_t
popcount_swar(uint32_t n) {
    n = n - ((n >> 1) & 0x55555555u);
    n = (n & 0x33333333u) + ((n >> 2) & 0x33333333u);
    n = (n + (n >> 4)) & 0x0f0f0f0fu;
    n = n + (n >> 8);
    n = n + (n >> 16);
    return n & 0x3fu;
}
